{

	scanf("%d",&n);

	for(int i=1;i<=2*n;i++)

	{

		scanf(" %c %d",mode+i,val+i);

		if(mode[i]=='B')dpb[i-1][val[i]]++,posb[val[i]]=i;

		else dpw[i-1][val[i]]++,posw[val[i]]=i;

	}

	for(int i=2*n-1;i>=0;i--)

		for(int j=1;j<=n;j++)

		{

			dpb[i][j]+=dpb[i+1][j];

			dpw[i][j]+=dpw[i+1][j];

		}

	for(int i=0;i<=2*n;i++)

		for(int j=1;j<=n;j++)

		{

			dpb[i][j]+=dpb[i][j-1];

			dpw[i][j]+=dpw[i][j-1];

		}

	dp[0][0]=0;

	for(int i=1;i<=n;i++)

	{

		dp[i][0]=dp[i-1][0]+(posb[i]-i+dpb[posb[i]][i]+dpw[posb[i]][0]);

		dp[0][i]=dp[0][i-1]+(posw[i]-i+dpb[posw[i]][0]+dpw[posw[i]][i]);

	}

	for(int i=1;i<=n;i++)

		for(int j=1;j<=n;j++)

			dp[i][j]=min(dp[i-1][j]+(posb[i]-i-j+dpb[posb[i]][i]+dpw[posb[i]][j]),dp[i][j-1]+(posw[j]-i-j+dpb[posw[j]][i]+dpw[posw[j]][j]));

	printf("%d\n",dp[n][n]);

	return 0;

}

