// bit calculation[how many "1"] (= __builtin_popcount())

int bit_count(int n) {

	int cnt = 0;

	while (n > 0) {

		if (n % 2 == 1)cnt++;

		n /= 2;

	}

	return cnt;

}

mint POW(mint n, int p) {

	if (p == 0)return 1;

	if (p % 2 == 0) {

		mint t = POW(n, p / 2);

		return t * t;

	}

	return n * POW(n, p - 1);

}

